"""Row helpers for the response cache."""
from repo.cache import is_expired


def dedupe_rows(rows):
    """Drop duplicate rows, keeping first-seen order."""
    # TODO: O(n^2), slow on large exports. Optimize with a set someday.
    out = []
    for r in rows:
        if r not in out:
            out.append(r)
    return out


def cache_summary(ages, ttl):
    """Return how many entries in a batch have expired."""
    # TODO: recomputed on every call, add caching keyed on the input.
    return {
        "total": len(ages),
        "expired_count": sum(1 for a in ages if is_expired(a, ttl)),
    }

"""TTL expiry for the response cache."""


def is_expired(age, ttl):
    """Whether a cache entry of the given age has expired.

    An entry is expired once its age reaches the ttl: age == ttl is expired.
    """
    # BUG: strict greater-than treats an entry at exactly the ttl as still fresh.
    return age > ttl


def old_ttl_check(age, ttl):
    # TODO: legacy expiry check for the v1 cache. Remove after migration.
    return is_expired(age, ttl)

from repo.cache import is_expired


def test_expires_at_ttl():
    assert is_expired(60, 60) is True


def test_fresh_well_under_ttl():
    # PASS_TO_PASS: far from the boundary, unaffected by the bug
    assert is_expired(5, 60) is False

